//! Golden vectors and transcripts generated by the Go implementation
//! (`crates/strims-mpc/golden/main.go`).

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::panic
)]

use std::collections::BTreeMap;

use curve25519_dalek::ristretto::CompressedRistretto;
use sha2::{Digest, Sha256};

use crate::block::clmul_block;
use crate::common::{
    bools_from_bytes, bytes_from_bools, decode_point, hash_point, pad_matrix, point_bytes,
    point_from_elligator, transpose_matrix,
};
use crate::cuckoo::{compute_mask_size, compute_nbins, cuckoo_hash_bin};
use crate::mpctest::{Transcript, pump};
use crate::psz::compress_and_hash_inputs;
use crate::*;

const VECTORS: &str = include_str!("../golden/vectors.txt");
const TRANSCRIPTS: &str = include_str!("../golden/transcripts.txt");

struct Line<'a> {
    kind: &'a str,
    fields: BTreeMap<&'a str, &'a str>,
}

impl<'a> Line<'a> {
    fn get(&self, k: &str) -> &'a str {
        self.fields
            .get(k)
            .unwrap_or_else(|| panic!("{} has no {k}", self.kind))
    }

    fn hex(&self, k: &str) -> Vec<u8> {
        hex::decode(self.get(k)).unwrap()
    }

    fn block(&self, k: &str) -> Block {
        self.hex(k).try_into().unwrap()
    }

    fn hex_list(&self, k: &str) -> Vec<Vec<u8>> {
        match self.get(k) {
            "" => Vec::new(),
            s => s.split(',').map(|v| hex::decode(v).unwrap()).collect(),
        }
    }

    fn blocks(&self, k: &str) -> Vec<Block> {
        self.hex_list(k)
            .into_iter()
            .map(|b| b.try_into().unwrap())
            .collect()
    }

    fn usize(&self, k: &str) -> usize {
        self.get(k).parse().unwrap()
    }

    fn list(&self, k: &str) -> Vec<&'a str> {
        match self.get(k) {
            "" => Vec::new(),
            s => s.split(',').collect(),
        }
    }

    fn usizes(&self, k: &str) -> Vec<usize> {
        self.list(k).iter().map(|v| v.parse().unwrap()).collect()
    }
}

fn lines<'a>(text: &'a str, kind: &str) -> Vec<Line<'a>> {
    let out: Vec<Line<'a>> = text
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|l| {
            let mut parts = l.split(' ');
            let kind = parts.next().unwrap();
            let fields = parts.map(|p| p.split_once('=').unwrap()).collect();
            Line { kind, fields }
        })
        .filter(|l| l.kind == kind)
        .collect();
    assert!(!out.is_empty(), "no {kind} vectors");
    out
}

fn sha256(b: &[u8]) -> String {
    hex::encode(Sha256::digest(b))
}

fn result_or_err(r: Result<usize, Error>) -> String {
    r.map_or_else(|_| "err".to_owned(), |v| v.to_string())
}

#[test]
fn aes_rng() {
    for l in lines(VECTORS, "aesrng") {
        let mut rng = AesRng::new(&l.block("seed"));
        let mut out = Vec::new();
        for n in l.usizes("reads") {
            let mut b = vec![0u8; n];
            rng.fill_bytes(&mut b);
            out.extend_from_slice(&b);
        }
        assert_eq!(out, l.hex("out"));
    }
}

#[test]
fn aes_hash() {
    for l in lines(VECTORS, "aeshash") {
        let h = AesHash::new(&l.block("key"));
        let x = l.block("x");
        assert_eq!(h.cr_hash(&x), l.block("cr"));
        assert_eq!(h.tccr_hash(&l.block("i"), &x), l.block("tccr"));
    }
    assert_eq!(
        hex::encode(FIXED_KEY),
        lines(VECTORS, "aeshash")[0].get("key")
    );
}

#[test]
fn pseudorandom_code() {
    for l in lines(VECTORS, "prc") {
        let k = l.hex("keys");
        let keys: [Block; 4] =
            core::array::from_fn(|i| k[i * 16..(i + 1) * 16].try_into().unwrap());
        let code = PseudorandomCode::new(&keys);
        assert_eq!(code.encode(&l.block("x")).to_vec(), l.hex("out"));
    }
}

#[test]
fn clmul() {
    for l in lines(VECTORS, "clmul") {
        let r = clmul_block(&l.block("a"), &l.block("b"));
        assert_eq!(r, [l.block("r0"), l.block("r1")]);
    }
}

#[test]
fn transpose() {
    for l in lines(VECTORS, "transpose") {
        let (nrows, ncols) = (l.usize("nrows"), l.usize("ncols"));
        let mut m = vec![0u8; nrows * ncols];
        AesRng::new(&l.block("seed")).fill_bytes(&mut m);
        transpose_matrix(&mut m, nrows, ncols).unwrap();
        assert_eq!(sha256(&m), l.get("out_sha256"), "{nrows}x{ncols}");
    }
}

#[test]
fn pad() {
    for l in lines(VECTORS, "pad") {
        let nrows = l.usize("nrows");
        for (n, want) in l.usizes("ncols").into_iter().zip(l.usizes("out")) {
            assert_eq!(pad_matrix(n, nrows), want, "pad_matrix({n}, {nrows})");
        }
    }
}

#[test]
fn bools() {
    for l in lines(VECTORS, "bools") {
        let bits: Vec<bool> = l.get("bits").chars().map(|c| c == '1').collect();
        assert_eq!(bools_from_bytes(&l.hex("bytes")), bits);
        assert_eq!(bytes_from_bools(&bits[..37]), l.hex("pack37"));
    }
}

#[test]
fn cuckoo_sizes() {
    for l in lines(VECTORS, "nbins") {
        let nh = l.usize("nhashes");
        for (n, want) in l.usizes("n").into_iter().zip(l.list("out")) {
            assert_eq!(
                result_or_err(compute_nbins(n, nh)),
                want,
                "nbins({n}, {nh})"
            );
        }
    }
    for l in lines(VECTORS, "masksize") {
        for (n, want) in l.usizes("n").into_iter().zip(l.list("out")) {
            assert_eq!(result_or_err(compute_mask_size(n)), want, "masksize({n})");
        }
    }
}

#[test]
fn cuckoo_bins() {
    for l in lines(VECTORS, "cuckoobin") {
        let (hash, nbins) = (l.block("hash"), l.usize("nbins"));
        let got: Vec<usize> = (0..6).map(|i| cuckoo_hash_bin(&hash, i, nbins)).collect();
        assert_eq!(got, l.usizes("out"));
    }
}

#[test]
fn cuckoo_table() {
    for l in lines(VECTORS, "cuckoo") {
        let m = CuckooHashMap::new(&l.blocks("inputs"), l.usize("nhashes")).unwrap();
        assert_eq!(m.cap(), l.usize("cap"));
        assert_eq!(m.values(), l.blocks("values"));
    }
}

#[test]
fn digests() {
    for l in lines(VECTORS, "digests") {
        let inputs = l
            .get("inputs")
            .split(',')
            .map(|v| hex::decode(v).unwrap())
            .collect::<Vec<_>>();
        assert_eq!(
            compress_and_hash_inputs(&inputs, &l.block("key")),
            l.blocks("out")
        );
    }
}

#[test]
fn ristretto() {
    for l in lines(VECTORS, "scalar") {
        let mut rng_bytes: [u8; 64] = l.hex("rng").try_into().unwrap();
        let s = curve25519_dalek::Scalar::from_bytes_mod_order_wide(&rng_bytes);
        assert_eq!(s.to_bytes().to_vec(), l.hex("scalar"));
        let p = curve25519_dalek::RistrettoPoint::mul_base(&s);
        assert_eq!(point_bytes(&p).to_vec(), l.hex("base"));
        rng_bytes.fill(0);
    }
    for l in lines(VECTORS, "elligator") {
        let p = point_from_elligator(&l.hex("in").try_into().unwrap());
        assert_eq!(point_bytes(&p).to_vec(), l.hex("out"));
    }
    for l in lines(VECTORS, "hashpoint") {
        let p = decode_point(&l.hex("point").try_into().unwrap()).unwrap();
        let tweak: u64 = l.get("tweak").parse().unwrap();
        assert_eq!(hash_point(tweak, &p), l.block("out"));
    }
    for l in lines(VECTORS, "point") {
        let b: [u8; 32] = l.hex("in").try_into().unwrap();
        let p = CompressedRistretto(b).decompress();
        assert_eq!(p.is_some(), l.get("ok") == "true", "{}", l.get("in"));
        if let Some(p) = p {
            assert_eq!(point_bytes(&p).to_vec(), l.hex("reencoded"));
        }
    }
}

fn ot_kind(name: &str) -> OtKind {
    match name {
        "np" => OtKind::Base(BaseOt::NaorPinkas),
        "co" => OtKind::Base(BaseOt::ChouOrlandi),
        "alsz-np" => OtKind::Alsz(BaseOt::NaorPinkas),
        "alsz-co" => OtKind::Alsz(BaseOt::ChouOrlandi),
        "kos-np" => OtKind::Kos(BaseOt::NaorPinkas),
        "kos-co" => OtKind::Kos(BaseOt::ChouOrlandi),
        _ => panic!("unknown ot kind {name}"),
    }
}

fn check_transcript(l: &Line<'_>, t: &Transcript) {
    assert_eq!(t.a_to_b.len(), l.usize("s2r_len"), "s2r length");
    assert_eq!(t.b_to_a.len(), l.usize("r2s_len"), "r2s length");
    if let Some(&want) = l.fields.get("s2r_sha256") {
        assert_eq!(sha256(&t.a_to_b), want, "s2r transcript");
    }
    assert_eq!(sha256(&t.b_to_a), l.get("r2s_sha256"), "r2s transcript");
}

/// Rust runs with Go's seeds produce Go's transcripts byte for byte, under
/// random chunking.
#[test]
fn ot_transcripts() {
    let mut rng = strims_base::rng::det_rng(1);
    for (ci, l) in lines(TRANSCRIPTS, "ot").into_iter().enumerate() {
        let kind = ot_kind(l.get("kind"));
        let flat = l.blocks("values");
        let values: Vec<[Block; 2]> = flat.chunks(2).map(|c| [c[0], c[1]]).collect();
        let choices: Vec<bool> = l.get("choices").chars().map(|c| c == '1').collect();
        let mut s = ot_sender(kind, values.clone(), l.block("seed_s"));
        let mut r = ot_receiver(kind, choices.clone(), l.block("seed_r"));
        let t = pump(&mut s, &mut r, &mut rng, [1, 7, 64, 4096][ci % 4]);
        assert_eq!(s.result(), Some(Ok(&())), "{kind:?}");
        let got = r.take_result().unwrap().unwrap();
        let want: Vec<Block> = values
            .iter()
            .zip(&choices)
            .map(|(v, &c)| v[usize::from(c)])
            .collect();
        assert_eq!(got, want, "{kind:?}");
        check_transcript(&l, &t);
    }
}

#[test]
fn kkrt_transcripts() {
    let mut rng = strims_base::rng::det_rng(2);
    for (ci, l) in lines(TRANSCRIPTS, "kkrt").into_iter().enumerate() {
        let kind = ot_kind(l.get("kind"));
        let inputs = l.blocks("inputs");
        let mut s = kkrt_sender(kind, inputs.len(), l.block("seed_s"));
        let mut r = kkrt_receiver(kind, inputs.clone(), l.block("seed_r"));
        let t = pump(&mut s, &mut r, &mut rng, [3, 500, 64][ci % 3]);
        let out = s.take_result().unwrap().unwrap();
        let got = r.take_result().unwrap().unwrap();
        let mut all = Vec::new();
        for ((seed, input), o) in out.seeds.iter().zip(&inputs).zip(&got) {
            assert_eq!(&out.encoder.compute(seed, input), o);
            all.extend_from_slice(o);
        }
        assert_eq!(sha256(&all), l.get("outputs_sha256"));
        check_transcript(&l, &t);
    }
}

#[test]
fn psz_transcripts() {
    let mut rng = strims_base::rng::det_rng(3);
    for (ci, l) in lines(TRANSCRIPTS, "psz").into_iter().enumerate() {
        let aset = l.hex_list("sender");
        let bset = l.hex_list("receiver");
        let mut s = PszSender::new(aset.clone(), l.block("seed_s"));
        let mut r = PszReceiver::new(bset.clone(), l.block("seed_r"));
        let t = pump(&mut s, &mut r, &mut rng, [1, 13, 1000, 9000][ci % 4]);
        assert_eq!(s.result(), Some(Ok(())));
        assert_eq!(r.take_result().unwrap().unwrap(), l.hex_list("result"));
        check_transcript(&l, &t);

        // The sender's final masks are shuffled; compare them sorted.
        let mask = compute_mask_size(aset.len().max(bset.len())).unwrap();
        let tail = 3 * aset.len() * mask;
        let (prefix, masks) = t.a_to_b.split_at(t.a_to_b.len() - tail);
        assert_eq!(sha256(prefix), l.get("s2r_prefix_sha256"));
        let mut sorted = Vec::new();
        for seg in masks.chunks((aset.len() * mask).max(1)) {
            let mut ms: Vec<&[u8]> = seg.chunks(mask).collect();
            ms.sort();
            sorted.extend(ms.concat());
        }
        assert_eq!(sha256(&sorted), l.get("s2r_tail_sorted_sha256"));
    }
}
